(function(){angular.module("app.core").filter("altDate",altDate);function altDate(){return function(value){var diff=Date.now()-new Date(value);if(diff<(60*60*1000)){return moment(value).fromNow()}else{if(diff<(60*60*24*1000)){return moment(value).format("HH:mm")
}else{if(diff<(60*60*24*7*1000)){return moment(value).format("dddd")}else{return moment(value).calendar()}}}}}})();